import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';

@Component({
  selector: 'app-contacte',
  templateUrl: './contacte.component.html',
  styleUrls: ['./contacte.component.css']
})
export class ContacteComponent implements OnInit {
  contactForm!: FormGroup;
  enviado: boolean = false;

  constructor(private fb: FormBuilder) {}

  ngOnInit(): void {
    this.contactForm = this.fb.group({
      nom: ['', [Validators.required, Validators.minLength(3)]],
      email: ['', [Validators.required, Validators.email]],
      telefon: ['', [Validators.pattern('^[0-9]{9}$')]],
      missatge: ['', [Validators.required, Validators.minLength(10)]]
    });
  }

  enviarFormulario(): void {
    if (this.contactForm.valid) {
      console.log('Datos enviados:', this.contactForm.value);
      this.enviado = true;
      alert('¡Gracias por contactar! Hemos recibido tu consulta.');
      this.contactForm.reset();
    }
  }
}
